from __future__ import annotations
import numpy as np
from scipy import stats


def loo_residual(x: np.ndarray, k: int = 3) -> np.ndarray:
    """x_i minus the mean of its neighbours within +/-k (leave-one-out high-pass)."""
    n = x.size
    c = np.concatenate([[0.0], np.cumsum(x)])
    i = np.arange(n)
    lo, hi = np.maximum(i - k, 0), np.minimum(i + k + 1, n)
    cnt = (hi - lo - 1).clip(min=1)
    return x - (c[hi] - c[lo] - x) / cnt


def robust_scale(r: np.ndarray) -> float:
    s = 1.4826 * np.median(np.abs(r - np.median(r)))
    return float(s if s > 0 else (r.std() if r.size else 0.0))


def winsorize(r: np.ndarray, c: float = 4.0) -> np.ndarray:
    s = robust_scale(r)
    return np.clip(r, -c * s, c * s) if s > 0 else r


def local_scale(r: np.ndarray, m: int = 129) -> np.ndarray:
    """Rolling RMS of the (winsorised) residual, centred window of m samples."""
    rr = winsorize(r) ** 2
    c = np.concatenate([[0.0], np.cumsum(rr)])
    i = np.arange(r.size)
    lo, hi = np.maximum(i - m // 2, 0), np.minimum(i + m // 2 + 1, r.size)
    return np.sqrt((c[hi] - c[lo]) / (hi - lo))


def z_to_p(z: float) -> float:
    return float(stats.norm.sf(z))


def stouffer(zs: list[float]) -> float:
    return float(np.sum(zs) / np.sqrt(len(zs))) if zs else 0.0
